#include <iostream>
#include <fstream>
#include <string>
#include <map>
using namespace std;

int main() {
    ifstream plik("sprzedaz.txt");
    string produkt;
    int ilosc;
    map<string, int> suma;
    while (plik >> produkt >> ilosc) {
        suma[produkt] += ilosc;
    }
    cout << "a) Sprzedaz per produkt:" << endl;
    string maxProd;
    int maxIle = 0;
    for (auto& p : suma) {
        cout << "   " << p.first << ": " << p.second << endl;
        if (p.second > maxIle) {
            maxIle = p.second;
            maxProd = p.first;
        }
    }
    cout << endl << "b) Najpopularniejszy produkt: " << maxProd << " (" << maxIle << ")" << endl;
    return 0;
}
```

